from __future__ import annotations

import re
from pathlib import Path

import thrombxai

ROOT = Path(thrombxai.__file__).resolve().parent.parent

FORBIDDEN = (
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "state-of-the-art",
    "cutting-edge",
    "seamlessly",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulously",
    "it's worth noting",
    "in conclusion",
)

EMOJI = re.compile(
    "[\U0001f300-\U0001faff\U00002600-\U000027bf\U0001f000-\U0001f0ff\U00002190-\U000021ff]"
)


def _targets() -> list[Path]:
    files = list((ROOT / "thrombxai").rglob("*.py"))
    files.append(ROOT / "README.md")
    files.append(ROOT / "Makefile")
    return [f for f in files if f.exists()]


def test_no_forbidden_phrases() -> None:
    for path in _targets():
        text = path.read_text().lower()
        for phrase in FORBIDDEN:
            assert phrase not in text, f"{path.name}: {phrase}"


def test_no_emoji() -> None:
    for path in _targets():
        assert EMOJI.search(path.read_text()) is None, path.name
